-- Additive lesson-plan storage; legacy lessons and attempts are untouched.
CREATE TABLE "lesson_plans" ("id" UUID NOT NULL PRIMARY KEY, "tenant_id" UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, "owner_id" UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, "title" VARCHAR(200) NOT NULL, "definition" JSONB NOT NULL, "revision" INTEGER NOT NULL DEFAULT 0, "review" JSONB, "updated_at" TIMESTAMP(3) NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "lesson_plans_tenant_owner_idx" ON "lesson_plans" (tenant_id,owner_id);
CREATE TABLE "lesson_plan_releases" ("id" UUID NOT NULL PRIMARY KEY, "tenant_id" UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, "owner_id" UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, "plan_id" UUID NOT NULL REFERENCES lesson_plans(id) ON DELETE CASCADE, "revision" INTEGER NOT NULL, "definition" JSONB NOT NULL, "source_excerpts" JSONB NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE (plan_id,revision));
CREATE INDEX "lesson_plan_releases_tenant_owner_idx" ON "lesson_plan_releases" (tenant_id,owner_id);
CREATE TABLE "lesson_shares" ("id" UUID NOT NULL PRIMARY KEY, "tenant_id" UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, "owner_id" UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, "release_id" UUID NOT NULL REFERENCES lesson_plan_releases(id) ON DELETE CASCADE, "token_hash" VARCHAR(64) NOT NULL, "revoked_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "lesson_shares_tenant_owner_idx" ON "lesson_shares" (tenant_id,owner_id);
CREATE TABLE "lesson_grants" ("id" UUID NOT NULL PRIMARY KEY, "tenant_id" UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, "owner_id" UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, "release_tenant_id" UUID NOT NULL, "release_id" UUID NOT NULL, "share_id" UUID NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(owner_id,share_id));
CREATE INDEX "lesson_grants_tenant_owner_idx" ON "lesson_grants" (tenant_id,owner_id);
CREATE TABLE "lesson_studies" ("id" UUID NOT NULL PRIMARY KEY, "tenant_id" UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, "owner_id" UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, "release_id" UUID NOT NULL REFERENCES lesson_plan_releases(id) ON DELETE CASCADE, "revision" INTEGER NOT NULL DEFAULT 0, "state" JSONB NOT NULL, "updated_at" TIMESTAMP(3) NOT NULL, UNIQUE(release_id,owner_id));
CREATE INDEX "lesson_studies_tenant_owner_idx" ON "lesson_studies" (tenant_id,owner_id);
CREATE FUNCTION protect_lesson_release() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Published lesson releases are immutable'; END $$;
CREATE TRIGGER immutable_lesson_release BEFORE UPDATE ON lesson_plan_releases FOR EACH ROW EXECUTE FUNCTION protect_lesson_release();
